const fs=require("fs");
const pages=["index.html","blog.html","publications.html"];
const html={}; pages.forEach(p=>html[p]=fs.readFileSync(p,"utf8"));
let bad=0;
const ids={};
for(const p of pages){
  ids[p]=new Set([...html[p].matchAll(/\bid="([^"]+)"/g)].map(m=>m[1]));
}
// link check
for(const p of pages){
  for(const m of html[p].matchAll(/href="([^"#]+)(#[^"]*)?"/g)){
    const [,file,frag]=m;
    if(/^(https?:|mailto:|data:)/.test(file)) continue;
    if(!fs.existsSync(file)){ console.log(`BROKEN FILE  ${p} -> ${file}`); bad=1; continue; }
    if(frag && ids[file] && !ids[file].has(frag.slice(1))){ console.log(`BROKEN FRAG  ${p} -> ${file}${frag}`); bad=1; }
  }
}
// required assets + nav parity
for(const p of pages){
  if(!/<link rel="stylesheet" href="assets\/css\/style.css">/.test(html[p])){console.log(`NO CSS LINK ${p}`);bad=1;}
  if(!/<html lang="en">/.test(html[p])){console.log(`NO LANG ${p}`);bad=1;}
  if(!/<meta name="viewport"/.test(html[p])){console.log(`NO VIEWPORT ${p}`);bad=1;}
  if(!/<title>/.test(html[p])){console.log(`NO TITLE ${p}`);bad=1;}
  const cur=[...html[p].matchAll(/aria-current="page"[^>]*>|>([^<]*)<\/a>/g)];
  if(!/aria-current="page"/.test(html[p])){console.log(`NO aria-current ${p}`);bad=1;}
  if(!/<a class="skip-link"/.test(html[p])){console.log(`NO skip-link ${p}`);bad=1;}
}
// unclosed tag sanity for the containers we use
for(const p of pages){
  for(const t of ["section","main","header","footer","ul","ol","li","article","nav","div","dl"]){
    const o=(html[p].match(new RegExp("<"+t+"[\\s>]","g"))||[]).length;
    const c=(html[p].match(new RegExp("</"+t+">","g"))||[]).length;
    if(o!==c){console.log(`TAG IMBALANCE ${p}: <${t}> ${o} open vs ${c} close`);bad=1;}
  }
}
console.log(bad? "LINK/MARKUP CHECK: FAILED" : "LINK/MARKUP CHECK: all internal links, anchors, assets and tag pairs OK");
process.exit(bad);
'; echo "check-exit=$?"

