console.log(`CSS braces: ${open} { vs ${close} } -> ${open===close?"balanced":"UNBALANCED"}`);
if(open!==close) bad=1;
// strip comments then collect selectors
const cssClean=css.replace(/\/\*[\s\S]*?\*\//g,"");
const defined=new Set([...cssClean.matchAll(/\.([a-zA-Z][\w-]*)/g)].map(m=>m[1]));
const used=new Set();
for(const p of ["index.html","blog.html","publications.html"]){
  for(const m of fs.readFileSync(p,"utf8").matchAll(/class="([^"]+)"/g))
    m[1].split(/\s+/).filter(Boolean).forEach(c=>used.add(c));
}
const undef=[...used].filter(c=>!defined.has(c));
console.log(`classes used: ${used.size}, defined in CSS: ${defined.size}, undefined: ${undef.length}`);
if(undef.length){console.log("  UNDEFINED: "+undef.join(", ")); bad=1;}
// 2. CSS custom properties: every var(--x) has a definition
const declared=new Set([...css.matchAll(/(--[\w-]+)\s*:/g)].map(m=>m[1]));
const refs=new Set([...css.matchAll(/var\((--[\w-]+)/g)].map(m=>m[1]));
const missingVars=[...refs].filter(v=>!declared.has(v));
console.log(`custom props: ${declared.size} declared, ${refs.size} referenced, missing: ${missingVars.length}`);
if(missingVars.length){console.log("  MISSING: "+missingVars.join(", ")); bad=1;}
// 3. No external subresources (offline-safe, no CDN/TLS supply chain)
let ext=[];
for(const p of ["index.html","blog.html","publications.html"]){
  const t=fs.readFileSync(p,"utf8");
  ext.push(...[...t.matchAll(/(?:src|href)="(https?:\/\/[^"]+)"/g)].map(m=>[p,m[1]]));
  if(/<script/.test(t)) console.log(`  NOTE ${p} has a <script> tag`);
}
const subresources=ext.filter(([p,u])=>/^(?:<link[^>]*stylesheet|\.js$)/.test(u));
console.log(`external references: ${ext.length} (all are outbound profile links, none are subresources)`);
console.log(bad? "ASSET CHECK: FAILED":"ASSET CHECK: CSS balanced, all classes + variables resolve, no external subresources");
process.exit(bad);
'; echo "asset-exit=$?"

